script:
card({
  name: 'Photo of the Week',
  icon: 'photo',
  permissions: ['pictures', 'chat_images', 'files', 'sound'],
  // The board bot only reads the result, to keep the relay's hall of
  // fame. The votes are the card's own.
  bots: { board: { grants: ['card.read'] } },
});

// A week to enter and vote, then anyone crowns the winner. The
// card decides everything; the board bot hears 'crown' and copies the
// winner to the relay's hall of fame.
const WEEK = 7 * 24 * 60 * 60 * 1000;

on.enter = (state, args, ctx) => {
  if (ctx.slot) throw 'Bots don\'t enter';
  if (ctx.time >= state.endsAt) throw 'This week is over';
  if (state.entries[ctx.author]) throw 'One photo each';
  // args.file is what upload() sent: the message the photo went in.
  state.entries[ctx.author] = { photo: args.file.message, name: ctx.authorName, votes: 0, at: ctx.time };
  ctx.sound('pop');
};

on.vote = (state, args, ctx) => {
  if (ctx.slot) throw 'Bots don\'t vote';
  if (ctx.time >= state.endsAt) throw 'This week is over';
  if (!state.entries[args.for]) throw 'No such photo';
  if (args.for === ctx.author) throw 'Pick someone else\'s';
  const before = state.voted[ctx.author];
  if (before) state.entries[before].votes -= 1;
  state.voted[ctx.author] = args.for;
  state.entries[args.for].votes += 1;
};

// Most votes wins; on a tie, the photo entered first.
on.crown = (state, args, ctx) => {
  if (ctx.time < state.endsAt) throw 'The week isn\'t over yet';
  if (state.winner !== null) throw 'Already crowned';
  const ids = Object.keys(state.entries);
  ids.sort((a, b) => state.entries[b].votes - state.entries[a].votes || state.entries[a].at - state.entries[b].at);
  state.winner = ids.length > 0 ? ids[0] : '';
};

function init(ctx) {
  return { entries: {}, voted: {}, endsAt: ctx.time + WEEK, winner: null };
}

function view(state, me, now, local) {
  const ids = Object.keys(state.entries);
  ids.sort((a, b) => state.entries[b].votes - state.entries[a].votes);
  const wide = me.card.width > 420;
  const over = now >= state.endsAt;
  const won = state.winner ? state.entries[state.winner] : null;
  return column([
    cover('sender', { height: wide ? 120 : 64 }),
    text('Photo of the Week', { size: 'large', bold: true }),
    won ? text('🏆 ' + won.name + ' wins with ' + won.votes + ' votes') : null,
    state.winner === '' ? text('No photos this week', { tone: 'muted' }) : null,
    ...ids.map((id) => row([
      avatar(id, { size: 28, round: true }),
      chatImage(state.entries[id].photo, { height: wide ? 160 : 96 }),
      over
        ? text('♥ ' + state.entries[id].votes)
        : button('♥ ' + state.entries[id].votes, 'vote', { for: id }),
    ])),
    over
      ? (state.winner === null ? button('Crown the winner 🏆', 'crown', {}, { tone: 'accent' }) : null)
      : state.entries[me.id]
        ? text('You\'re in. Vote for a favourite.', { tone: 'muted' })
        : upload('Enter a photo', 'enter', 'image'),
  ]);
}

function pause(local, ctx) {
  // Runs on this phone when the card leaves the screen.
}

function resume(local, ctx) {
  // Runs on this phone when it comes back.
}
